def transform(grid):
    rows = len(grid)
    if rows == 0:
        return grid
    cols = len(grid[0])

    from collections import deque, Counter

    # Find all connected components using 8-connectivity
    visited = [[False]*cols for _ in range(rows)]
    all_components = []

    for r in range(rows):
        for c in range(cols):
            if not visited[r][c]:
                color = grid[r][c]
                positions = []
                queue = deque([(r, c)])
                visited[r][c] = True

                while queue:
                    cr, cc = queue.popleft()
                    positions.append((cr, cc))

                    for dr in [-1, 0, 1]:
                        for dc in [-1, 0, 1]:
                            if dr == 0 and dc == 0:
                                continue
                            nr, nc = cr + dr, cc + dc
                            if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc] and grid[nr][nc] == color:
                                visited[nr][nc] = True
                                queue.append((nr, nc))

                all_components.append((color, positions))

    # Determine which components are structural (form rectangular regions)
    # Structural = each row of positions covers consecutive columns
    structural_components = set()
    for color, positions in all_components:
        if len(positions) >= 4:  # Minimum size for structural
            structural_components.add(color)

    # Build output by replacing noise with appropriate values
    result = []
    for r in range(rows):
        new_row = []
        for c in range(cols):
            val = grid[r][c]

            # If this cell is part of a structural component, keep it
            if any(val == comp[0] for comp in all_components if len(comp[1]) >= 4):
                new_row.append(val)
            else:
                # Noise value - replace with most common 8-connected neighbor
                neigh = []
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            neigh.append(grid[nr][nc])

                if neigh:
                    counts = Counter(neigh)
                    # Get max count, then pick first value with that count
                    max_count = max(counts.values())
                    for v in neigh:
                        if counts[v] == max_count:
                            new_row.append(v)
                            break
                else:
                    new_row.append(2)  # fallback background
        result.append(new_row)

    return result
